// Milestones derive from saved best stars; no currency purchase or manual claim.
function updateChallengeRewards(){const total=challengeStarTotal(),next=challengeCosmeticRewards.find(r=>total<r.stars);$('challengeStarCount').textContent='★ '+total+' / 9';$('challengeStarBar').value=total;$('challengeNextReward').textContent=next?'다음 ★'+next.stars+' · '+next.name:'전체 해금 · 도전 항로 정복자';}
const rewardsRenderChallenges=renderChallenges;renderChallenges=function(...args){normalizeCosmetics();const out=rewardsRenderChallenges(...args);updateChallengeRewards();return out;};
function openChallengeRewardShop(){const total=challengeStarTotal(),reward=[...challengeCosmeticRewards].reverse().find(r=>total>=r.stars)||challengeCosmeticRewards[0];showMenu('shop');cosmeticTab=reward.type;cosmeticSelection=reward.id;cosmeticPending=null;shopMessage='도전 항로 전용 보상 · 별 3개 도색 / 6개 불꽃 / 9개 항적·배지';renderShopInterface();}
$('challengeRewardOpen').onclick=openChallengeRewardShop;
const rewardsFinishChallenge=finishChallenge;finishChallenge=function(win,reason){const eligible=challengeActive&&!challengeSettled&&state==='play',oldOwned=challengeCosmeticRewards.filter(r=>data.cosmetics[r.type].owned.includes(r.id)).length;const out=rewardsFinishChallenge(win,reason);if(eligible&&state==='win'&&storageOK){reconcileChallengeCosmetics(data);awardBadges();save();const fresh=challengeCosmeticRewards.slice(oldOwned).filter(r=>challengeStarTotal()>=r.stars);if(fresh.length)$('challengeResultReward').textContent+=' · 보상 해금: '+fresh.map(r=>r.name).join(' / ');}return out;};
const rewardsBackup=validateBackup;validateBackup=function(raw){const out=rewardsBackup(raw);reconcileChallengeCosmetics(out.game);if(challengeStarTotal(out.game)>=9&&!out.game.badges.unlocked.challenge9)out.game.badges.unlocked.challenge9=new Date().toISOString();return out;};
// Reconcile older saves immediately, without changing equipped cosmetics.
reconcileChallengeCosmetics(data);awardBadges(false);if(challengeStarTotal()>=3)save();updateChallengeRewards();
